mapper.update:
update t_device
device_no = #{deviceNo}, device_name = #{deviceName}, device_charge = #{deviceCharge}, device_charge_acct = #{deviceChargeAcct}, expire_date = #{expireDate}, updated_by = #{updatedBy}, updated_time = now()
where id = #{id}

mapper.select:
select td.id as deviceId, td.device_no as deviceNo, td.device_name as deviceName, tdd.device_type as deviceType, tdd.device_model as deviceModel, tdd.device_system as deviceSystem, tdd.device_system_version as deviceSystemVersion, td.device_status as deviceStatus, td.device_charge as deviceCharge, td.device_charge_acct as deviceChargeAcct, td.expire_date as expireDate from t_device td left join t_device_detail tdd on td.id = tdd.device_id
td.del_flag = 'N'
and tdd.device_type in
#{deviceType}
and td.device_name like concat('%',#{queryDTO.deviceName},'%')
and td.device_no = #{queryDTO.deviceNo}
and td.device_charge = #{queryDTO.deviceCharge}
and td.device_status in
#{deviceStatus}
order by td.updated_time desc

select
tdf.id,
tdf.content,
tdf.created_time as date,
tdf.handle_result as handleResult,
td.device_no as deviceNo
from t_device_feedback tdf
inner join t_device td on td.id = tdf.device_id

    td.del_flag = 0


        and tdf.handle_result = #{queryDTO.handleResult}


        and td.device_no = #{queryDTO.deviceNo}


         and t.created_time >= #{feedbackStartTime} 


         and t.created_time <= #{feedbackEndTime}
